import re, glob, os, subprocess

files = sorted(glob.glob('logs/app-*.log'))

starts, dones, errors = set(), set(), set()
for f in files:
    for line in open(f, encoding='utf-8', errors='replace'):
        m = re.search(r'req-\d+', line)
        if not m:
            continue
        rid = m.group(0)
        low = line.lower()
        if 'start' in low:
            starts.add(rid)
        if 'done' in low:
            dones.add(rid)
        if 'error' in low:
            errors.add(rid)

stuck = sorted(starts & errors - dones)

os.makedirs('out', exist_ok=True)
with open('out/stuck.txt', 'w', encoding='utf-8') as fh:
    for rid in stuck:
        fh.write(rid + "\n")

print("Wrote", len(stuck), "stuck ids to out/stuck.txt:")
print(subprocess.run(['cat', 'out/stuck.txt'], capture_output=True, text=True).stdout)
